// Extract GitHub issue/discussion payload and auto-detect Live URLs & Video URLs
const payload = $input.first().json.body || $input.first().json;

// Handle GitHub Issue or Discussion payloads
const discussion = payload.discussion || payload.issue || {};
const repository = payload.repository || {};

const title = discussion.title || payload.title || "Reported UI/Console Bug";
const body = discussion.body || payload.body || "";
const issueNumber = discussion.number || payload.number || 0;
const repoOwner = repository.owner ? (repository.owner.login || repository.owner.name) : "";
const repoName = repository.name || "";

// Extract video URL if present (mp4, webm, mov, or loom/youtube/github asset link)
let videoUrl = "";
const videoMatch = body.match(/(https?:\/\/[^\s"'<>]+\.(?:mp4|webm|mov|mkv))/i) || 
                 body.match(/(https?:\/\/user-images\.githubusercontent\.com\/[^\s"'<>]+)/i) ||
                 body.match(/(https?:\/\/(?:www\.)?(?:loom\.com|youtube\.com)\/[^\s"'<>]+)/i);
if (videoMatch) {
  videoUrl = videoMatch[0];
}

// Auto-detect Live Deployment URL (Vercel, Netlify, Render, Staging, or any http/https URL in report)
let liveUrl = "";
const urlRegex = /(https?:\/\/[a-zA-Z0-9.-]+\.(?:vercel\.app|netlify\.app|pages\.dev|koyeb\.app|onrender\.com|dev|io|org|com)(?:\/[^\s"'<>]*)?)/gi;
let match;
while ((match = urlRegex.exec(body)) !== null) {
  const foundUrl = match[1];
  if (!foundUrl.includes("github.com") && !foundUrl.includes("githubusercontent.com") && !foundUrl.includes("loom.com")) {
    liveUrl = foundUrl;
    break;
  }
}

return [{
  json: {
    title,
    body,
    issueNumber,
    repoOwner,
    repoName,
    video_url: videoUrl,
    live_url: liveUrl
  }
}];
